.var _hpt_tone_C2_HPT_01[48] =
    0x00000000, 0x0216A2A2, 0x04241F70, 0x061F78A9, 0x07FFFFFF, 0x09BD7C9F, 0x0B504F33, 0x0CB19345,
    0x0DDB3D73, 0x0EC835E7, 0x0F746EA3, 0x0FDCF548, 0x0FFFFFFF, 0x0FDCF548, 0x0F746EA3, 0x0EC835E7,
