#if DSP4_BLOCK_KERNELS
.global _blk_C2_HPT_01;
.var _blk_C2_HPT_01[DSP4_BLOCK_SIZE];
#endif
.global _buf_C2_HPT_01;
.var _buf_C2_HPT_01 = 0;

.section/pm seg_pmco;

.global _C2_HPT_01_process;
_C2_HPT_01_process:
#if DSP4_BLOCK_KERNELS
    l0 = 0;
    l1 = 0;
    l2 = 0;

    /* ---- the trigger, consumed exactly once ---- */
    r0 = dm(_hpt_trig_C2_HPT_01);
    r0 = pass r0;
    if eq jump (pc, .hpt_ntrig_C2_HPT_01);
    r1 = 0;
    dm(_hpt_trig_C2_HPT_01) = r1;
    r2 = dm(_hpt_sample_C2_HPT_01);
    r3 = 1;
    r2 = r2 - r3;                 /* 1..3 -> 0..2 */
    r3 = 0;
    comp(r2, r3);
    if lt r2 = r3;                /* clamp: an out-of-range sample */
    r3 = 2;
    comp(r2, r3);
    if gt r2 = r3;                /*   plays the nearest one */
    m1 = r2;
    i2 = _hpt_off_C2_HPT_01;
    modify(i2, m1);
    r4 = dm(i2, 0);               /* offset into the table */
    i2 = _hpt_len_C2_HPT_01;
    modify(i2, m1);
    r5 = dm(i2, 0);               /* its length in samples */
    m1 = r4;
    i2 = _hpt_tab_C2_HPT_01;
    modify(i2, m1);
    r4 = i2;                      /* -> an ADDRESS, not an offset */
    dm(_hpt_pos_C2_HPT_01) = r4;
    dm(_hpt_rem_C2_HPT_01) = r5;
    r1 = 1;
    dm(_hpt_busy_C2_HPT_01) = r1;
.hpt_ntrig_C2_HPT_01:
    r7 = dm(_hpt_busy_C2_HPT_01);
    r7 = pass r7;
    if eq jump (pc, .hpt_nclick_C2_HPT_01);

    /* ================= A CLICK IS PLAYING ================= */
    f1 = dm(_hpt_level_C2_HPT_01);
    r4 = 0x4D800000;              /* 2^28 as a float */
    f2 = r4;
    f1 = f1 * f2;
    r12 = fix f1;                 /* level as a Q4.28 coefficient */
    i0 = dm(_hpt_pos_C2_HPT_01);
    i1 = _blk_C2_HPT_01;
    r5 = dm(_hpt_rem_C2_HPT_01);
    r6 = DSP4_BLOCK_SIZE;
    comp(r5, r6);
    if lt r6 = r5;                /* n = min(remaining, BLOCK); the
                                   * busy flag guarantees n >= 1, and
                                   * a hardware loop with lcntr = 0
                                   * runs 2^32 times, so that is the
                                   * invariant this rests on */
    r7 = 0x08000000;              /* 2^27, the round half */
    r13 = 1;
    r10 = 0x7FFFFFFF;
    lcntr = r6, do .hpt_clp_C2_HPT_01 until lce;
        r0 = dm(i0, 1);
        mrf = r0 * r12 (ssi);
        mrf = mrf + r7 * r13 (ssi);
        r8 = mr0f;
        r2 = mr1f;
        r8 = lshift r8 by -28;
        r9 = lshift r2 by 4;
        r0 = r8 or r9;
        r8 = ashift r2 by -28;
        r9 = ashift r0 by -31;
        r11 = ashift r2 by -31;
        r11 = r10 xor r11;
        comp(r8, r9);
        if ne r0 = r11;
    .hpt_clp_C2_HPT_01: dm(i1, 1) = r0;
    r4 = i0;
    dm(_hpt_pos_C2_HPT_01) = r4;
    r5 = r5 - r6;
    dm(_hpt_rem_C2_HPT_01) = r5;
    r5 = pass r5;
    if ne jump (pc, .hpt_ctail_C2_HPT_01);
    r4 = 0;
    dm(_hpt_busy_C2_HPT_01) = r4;        /* the click has finished */
.hpt_ctail_C2_HPT_01:
    /* whatever is left of the block is silence, in the SAME block --
     * a click that ends mid-block must not leave stale samples on
     * the wire. */
    r4 = DSP4_BLOCK_SIZE;
    r4 = r4 - r6;
    r4 = pass r4;
    if eq jump (pc, .hpt_cdone_C2_HPT_01);
    r0 = 0;
    lcntr = r4, do .hpt_czl_C2_HPT_01 until lce;
    .hpt_czl_C2_HPT_01: dm(i1, 1) = r0;
.hpt_cdone_C2_HPT_01:
    r4 = 0;
    dm(_hpt_zero_C2_HPT_01) = r4;
    dm(_buf_C2_HPT_01) = r0;
    rts;

.hpt_nclick_C2_HPT_01:
    r7 = dm(_hpt_test_on_C2_HPT_01);
    r7 = pass r7;
    if eq jump (pc, .hpt_silent_C2_HPT_01);

    /* ================= THE STEADY TEST TONE ================= */
    /* One exact period in a circular buffer: the wrap costs nothing
     * and the phase is continuous across blocks, so the tone the
     * acoustic self-test measures has no seam to fit. */
    f1 = dm(_hpt_test_level_C2_HPT_01);
    r4 = 0x4D800000;
    f2 = r4;
    f1 = f1 * f2;
    r12 = fix f1;
    i1 = _blk_C2_HPT_01;
    l2 = 48;
    b2 = _hpt_tone_C2_HPT_01;            /* sets i2 = the base */
    m1 = dm(_hpt_tph_C2_HPT_01);
    modify(i2, m1);               /* ... + the running phase */
    r7 = 0x08000000;
    r13 = 1;
    r10 = 0x7FFFFFFF;
    lcntr = DSP4_BLOCK_SIZE, do .hpt_tlp_C2_HPT_01 until lce;
        r0 = dm(i2, 1);
        mrf = r0 * r12 (ssi);
        mrf = mrf + r7 * r13 (ssi);
        r8 = mr0f;
        r2 = mr1f;
        r8 = lshift r8 by -28;
        r9 = lshift r2 by 4;
        r0 = r8 or r9;
        r8 = ashift r2 by -28;
        r9 = ashift r0 by -31;
        r11 = ashift r2 by -31;
        r11 = r10 xor r11;
        comp(r8, r9);
        if ne r0 = r11;
    .hpt_tlp_C2_HPT_01: dm(i1, 1) = r0;
    l2 = 0;
    /* phase = (phase + BLOCK) mod 48 -- one conditional subtract,
     * which is why BLOCK may not exceed the period. */
    r4 = dm(_hpt_tph_C2_HPT_01);
    r5 = DSP4_BLOCK_SIZE;
    r4 = r4 + r5;
    r5 = 48;
    comp(r4, r5);
    if ge r4 = r4 - r5;
    dm(_hpt_tph_C2_HPT_01) = r4;
    r4 = 0;
    dm(_hpt_zero_C2_HPT_01) = r4;
    dm(_buf_C2_HPT_01) = r0;
    rts;

.hpt_silent_C2_HPT_01:
    /* ================= SILENCE, WRITTEN ONCE ================= */
    r4 = dm(_hpt_zero_C2_HPT_01);
    r4 = pass r4;
    if ne rts;                    /* the whole idle path is fifteen
                                   * instructions, every block, for
                                   * ever */
    r0 = 0;
    i1 = _blk_C2_HPT_01;
    lcntr = DSP4_BLOCK_SIZE, do .hpt_zlp_C2_HPT_01 until lce;
    .hpt_zlp_C2_HPT_01: dm(i1, 1) = r0;
    dm(_buf_C2_HPT_01) = r0;
    r4 = 1;
    dm(_hpt_zero_C2_HPT_01) = r4;
    rts;
#else
    /* PER-SAMPLE BUILD (DSP4_BLOCK_KERNELS=0): a measurement control
     * arm that has never shipped. The speaker is SILENT on it, and
     * saying so here is cheaper and more honest than a second
     * hand-written kernel no product would ever run. */
    r0 = 0;
    dm(_buf_C2_HPT_01) = r0;
    rts;
#endif
_C2_HPT_01_process.end:
